<?php
declare(strict_types=1);
namespace App\Application\QuestionBank\Service;
use App\Application\Assistant\Port\AssistantProviderInterface;use App\Application\Catalog\Port\PdfTextExtractorInterface;use App\Application\QuestionBank\Port\QuestionPdfQuestionWriterInterface;use App\Domain\Assistant\ValueObject\SyllabusEvidence;use App\Domain\QuestionBank\Entity\QuestionPdfImportJob;use App\Domain\QuestionBank\Repository\QuestionPdfImportJobRepositoryInterface;use App\Domain\Taxonomy\Repository\TaxonomySubjectRepositoryInterface;
final class ProcessQuestionPdfImportJobService { public function __construct(private readonly QuestionPdfImportJobRepositoryInterface $jobs,private readonly PdfTextExtractorInterface $pdf,private readonly AssistantProviderInterface $ai,private readonly TaxonomySubjectRepositoryInterface $taxonomy,private readonly QuestionPdfQuestionWriterInterface $writer){} public function processNext():bool{$job=$this->jobs->claimNext();if($job===null)return false;try{$pages=$this->pdf->extractPages($job->documentPath);$candidates=[];foreach($pages as $i=>$text)if($this->hasQuestion($text))$candidates[$i+1]=$text;$job=$this->state($job,12,count($pages),count($candidates));$this->jobs->save($job);$created=0;$duplicates=0;$classified=0;$extracted=0;$failed=0;$newSubjects=0;$chunks=array_chunk($candidates,3,true);foreach($chunks as $i=>$chunk){$questions=$this->extract($chunk);$result=$this->writer->write($job->createdBy,$questions);$extracted+=count($questions);$created+=$result['created'];$duplicates+=$result['duplicates'];$classified+=$result['classified'];$failed+=$result['failed'];$newSubjects+=$result['createdSubjects'];$job=$this->state($job,min(98,12+(int)floor((($i+1)/max(1,count($chunks)))*86)),count($pages),count($candidates),$extracted,$classified,$created,$duplicates,$failed,$newSubjects);$this->jobs->save($job);}$this->jobs->save($this->state($job,100,count($pages),count($candidates),$extracted,$classified,$created,$duplicates,$failed,$newSubjects,'COMPLETED'));}catch(\Throwable $e){error_log('Question PDF job '.$job->id.': '.$e::class.' '.$e->getMessage());$this->jobs->save($this->state($job,$job->progress,$job->pageCount,$job->candidatePages,$job->extractedQuestions,$job->classifiedQuestions,$job->createdQuestions,$job->duplicateQuestions,$job->failedQuestions,$job->createdTaxonomySubjects,'FAILED','Nao foi possivel processar este PDF.'));}return true;} private function extract(array $pages):array{$evidence=[];foreach($pages as $page=>$text)$evidence[]=new SyllabusEvidence((int)$page,mb_substr($text,0,14000));$names=array_map(static fn($s)=>$s->name,$this->taxonomy->list(0,1000));$prompt='Retorne SOMENTE JSON válido, sem markdown: {"questions":[{"statement":"...","options":[{"content":"..."}],"board":"... ou null","exam":"... ou null","year":2024 ou null,"subject":"um assunto canônico da lista ou null","difficulty":"EASY|MEDIUM|HARD"}]}. Extraia exclusivamente questões objetivas completas presentes nas páginas. Preserve enunciado e alternativas, não invente gabarito. Identifique banca, concurso e ano apenas quando estiverem explicitamente impressos no bloco. Classifique pelo assunto mais específico desta lista canônica: '.implode(' | ',array_slice($names,0,700)).'. Ignore comentários, teoria, exercícios sem alternativas e gabaritos.';$raw=$this->ai->answer($prompt,$evidence)->content;$text=trim(preg_replace('/^\x60\x60\x60(?:json)?|\x60\x60\x60$/m','',$raw)??$raw);$data=json_decode($text,true);return is_array($data)&&is_array($data['questions']??null)?array_values(array_filter($data['questions'],static fn($q)=>is_array($q)&&is_string($q['statement']??null)&&is_array($q['options']??null))):[];} private function hasQuestion(string $text):bool{return preg_match('/(?:quest.{0,3}o|\b\d{1,3}\s*[.)-])[^\n]{0,300}/iu',$text)===1&&preg_match_all('/(?:^|\n)\s*(?:\(?[A-Ea-e]\)|[A-Ea-e][.)])/u',$text)>1;} private function state(QuestionPdfImportJob $j,int $progress,int $pages,int $candidates,int $extracted=0,int $classified=0,int $created=0,int $duplicates=0,int $failed=0,int $newSubjects=0,string $status='PROCESSING',?string $error=null):QuestionPdfImportJob{return new QuestionPdfImportJob($j->id,$j->syllabusId,$j->createdBy,$j->documentPath,$j->documentSha256,$j->documentOriginalName,$status,$progress,$pages,$candidates,$extracted,$classified,$created,$duplicates,$failed,$newSubjects,$error,$j->createdAt,$j->startedAt,$status==='COMPLETED'||$status==='FAILED'?new \DateTimeImmutable('now'):null);} }
